#!/usr/bin/env node
// sync-translate-prompts.mjs — regenerate api/src/translate/prompts/translate*.ts
// from a bp-assistant-skills checkout (issue #445, design §A "Prompt fidelity").
//
// The Worker cannot read SKILL.md off disk the way the bot does, so each
// translate skill's body (YAML frontmatter stripped, trimmed — the exact
// algorithm of translate-llm.js stripFrontmatter) is checked in as a string
// constant. Re-run this whenever the skills repo changes a translate-* skill,
// then commit the regenerated files; api/src/translate/prompts.test.mjs
// compares the constants against the checkout when one is present.
//
// The body is read from the COMMITTED blob at the skills repo's origin/main
// (`git show origin/main:<path>`), never from the working tree: the local
// checkout is a live repo that sibling sessions switch between branches, and
// the first generation captured an unmerged review branch's wording for
// translate-tn. origin/main is what the bot deploys. Run `git fetch` in the
// skills repo first if you need the very latest; the generator stamps the
// commit it read so drift is visible.
//
// Usage (from repo root):
//   node scripts/sync-translate-prompts.mjs [--skills <bp-assistant-skills dir>] [--ref <git ref>] [--out <prompts dir>]
//   BP_SKILLS_DIR=<dir> BP_SKILLS_REF=<ref> node scripts/sync-translate-prompts.mjs

import { writeFileSync, existsSync, mkdirSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { fileURLToPath } from "node:url";
import path from "node:path";

export const DEFAULT_SKILLS_REF = "origin/main";

const SKILLS = [
  { skill: "translate-tn", file: "translateTn.ts", constant: "TRANSLATE_TN_SKILL_BODY" },
  { skill: "translate-tq", file: "translateTq.ts", constant: "TRANSLATE_TQ_SKILL_BODY" },
  { skill: "translate-article", file: "translateArticle.ts", constant: "TRANSLATE_ARTICLE_SKILL_BODY" },
];

const DEFAULT_SKILLS_DIRS = [
  process.env.BP_SKILLS_DIR,
  "C:/GH/bp-bot/bp-assistant-skills",
  path.resolve(process.env.HOME || process.env.USERPROFILE || ".", "bp-bot/bp-assistant-skills"),
].filter(Boolean);

function arg(name) {
  const i = process.argv.indexOf(name);
  return i !== -1 ? process.argv[i + 1] : undefined;
}

// Line-ending independence: the skills repo stores every SKILL.md as LF
// (git ls-files --eol \u2192 i/lf), which is what the bot on Fly reads. A Windows
// checkout with core.autocrlf=true hands us CRLF for the same blob, and the
// bot's stripFrontmatter leaves interior \r\n alone \u2014 so without this the
// generated tq/article prompts carried 87-89 stray \r that production never
// sends. Normalize BEFORE stripping and hashing; prompts.test.mjs applies the
// same normalization when it compares against a checkout.
export function normalizeEol(text) {
  return text.replace(/\r\n/g, "\n");
}

// Verbatim port of bp-assistant src/lib/translate-llm.js stripFrontmatter.
export function stripFrontmatter(text) {
  const normalized = text.replace(/^\uFEFF/, "");
  if (!/^---\r?\n/.test(normalized)) return normalized.trim();
  const end = normalized.indexOf("\n---", 3);
  if (end === -1) return normalized.trim();
  const after = normalized.indexOf("\n", end + 1);
  return (after === -1 ? "" : normalized.slice(after + 1)).trim();
}

/** Repo-relative path of a translate skill's SKILL.md (forward slashes: it is a git path). */
export function skillGitPath(skill) {
  return `.claude/skills/${skill}/SKILL.md`;
}

/** The committed SKILL.md blob at `ref` in the skills repo (throws if git cannot show it). */
export function readCommittedSkill(skillsDir, skill, ref = DEFAULT_SKILLS_REF) {
  return execFileSync("git", ["-C", skillsDir, "show", `${ref}:${skillGitPath(skill)}`], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] });
}

export function resolveSkillsCommit(skillsDir, ref = DEFAULT_SKILLS_REF) {
  return execFileSync("git", ["-C", skillsDir, "rev-parse", ref], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
}

export function renderPromptModule({ skill, constant, body, sha256, ref, commit }) {
  return [
    `// GENERATED by scripts/sync-translate-prompts.mjs — do not edit by hand.`,
    `// Source: bp-assistant-skills ${ref} @ ${commit}, ${skillGitPath(skill)} (the committed`,
    `// blob, line endings normalized to LF), YAML frontmatter stripped and trimmed`,
    `// exactly as bp-assistant translate-llm.js readSkillBody does.`,
    `// sha256(body) = ${sha256}`,
    `// Regenerate: node scripts/sync-translate-prompts.mjs`,
    ``,
    `export const ${constant}: string = ${JSON.stringify(body)};`,
    ``,
  ].join("\n");
}

function main() {
  const skillsDir = arg("--skills") || DEFAULT_SKILLS_DIRS.find((d) => existsSync(d));
  if (!skillsDir || !existsSync(skillsDir)) {
    console.error("sync-translate-prompts: no bp-assistant-skills checkout found; pass --skills <dir> or set BP_SKILLS_DIR");
    process.exit(2);
  }
  const ref = arg("--ref") || process.env.BP_SKILLS_REF || DEFAULT_SKILLS_REF;
  const outDir = arg("--out") || fileURLToPath(new URL("../api/src/translate/prompts/", import.meta.url));
  mkdirSync(outDir, { recursive: true });

  let commit;
  try {
    commit = resolveSkillsCommit(skillsDir, ref);
  } catch (err) {
    console.error(`sync-translate-prompts: cannot resolve ${ref} in ${skillsDir} (${err.message.trim()}); run git fetch there or pass --ref`);
    process.exit(2);
  }
  console.log(`reading committed skills at ${ref} @ ${commit} from ${skillsDir}`);

  for (const { skill, file, constant } of SKILLS) {
    let raw;
    try {
      raw = readCommittedSkill(skillsDir, skill, ref);
    } catch (err) {
      console.error(`sync-translate-prompts: git show ${ref}:${skillGitPath(skill)} failed: ${err.message.trim()}`);
      process.exit(2);
    }
    const body = stripFrontmatter(normalizeEol(raw));
    if (body.includes("\r")) {
      console.error(`sync-translate-prompts: ${skill} still contains a bare \\r after normalization; refusing to write`);
      process.exit(2);
    }
    const sha256 = createHash("sha256").update(body, "utf8").digest("hex");
    const out = path.join(outDir, file);
    writeFileSync(out, renderPromptModule({ skill, constant, body, sha256, ref, commit }), "utf8");
    console.log(`wrote ${out} (${body.length} chars, sha256 ${sha256.slice(0, 12)})`);
  }
}

const invokedDirectly = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (invokedDirectly) main();
